  const buttonSet = figma.combineAsVariants(buttons.map(x => x[0]), board);
  buttonSet.name = 'Button';
  const labelProp = buttonSet.addComponentProperty('Label', 'TEXT', 'Button');
  for (const [, t] of buttons) t.componentPropertyReferences = { characters: labelProp };
  buttonSet.layoutMode = 'VERTICAL'; buttonSet.itemSpacing = 12;
  buttonSet.paddingLeft = buttonSet.paddingRight = buttonSet.paddingTop = buttonSet.paddingBottom = 16;
