    cam.primaryAxisAlignItems = 'CENTER'; cam.counterAxisAlignItems = 'CENTER'; cam.primaryAxisSizingMode = 'FIXED'; cam.counterAxisSizingMode = 'FIXED';
    row.appendChild(cam); cam.appendChild(icon('camera', 26, 'white'));
