  const fh = T('Helper text', 'Small', 'text-muted'); fh.name = 'Helper'; fd.appendChild(fh); fill(fh); fh.visible = false;
  fl.componentPropertyReferences = { characters: fd.addComponentProperty('Label', 'TEXT', 'Label') };
