    for (let i = 0; i < 4; i++) {
      const d = figma.createRectangle(); d.resize(i === index ? 28 : 10, 10);
      if (i === index) d.fills = [paint('white')]; else { d.fills = []; box(d, 'white', 1.5); }
      dots.appendChild(d);
    }
    const b = button('On red', L('onbNext')); bottom.appendChild(b); b.layoutSizingHorizontal = 'FIXED'; b.resize(120, 56);
